const kinds = [...new Set(CHECK_CATALOG.map(c => c.probe_profile?.kind).filter(Boolean))].sort();
const displayExecutor = (kind) => kind === 'ops_readiness' ? 'executeOpsReadinessProbe (control plane)' : executorNameForProbeKind(kind);
